      <footer class="cinema-story-footer"><a href="#/cinema">Все киноистории</a>${siblings.map((item) => `<a href="#/cinema/${encodeURIComponent(item.id)}">Следующий в разделе: <b>${escapeHtml(item.title)}</b> →</a>`).join("")}</footer>
